def seed_default_suite(apps, schema_editor):
    AuditSuite = apps.get_model("audit", "AuditSuite")
    AuditAgent = apps.get_model("audit", "AuditAgent")
    if AuditSuite.objects.filter(name="Project Overview").exists():
        return
    suite = AuditSuite.objects.create(
        name="Project Overview",
        description="Single lightweight specialist for local/token-constrained runs.",
        is_default=True,
        model="claude-haiku-4-5",
    )
    AuditAgent.objects.create(suite=suite, position=0, enabled=True, **_DEFAULT_AGENT)


def unseed_default_suite(apps, schema_editor):
    AuditSuite = apps.get_model("audit", "AuditSuite")
    AuditSuite.objects.filter(name="Project Overview").delete()


